import * as React from "react";

import { FrameScope, useInFrame } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { Code, type CodeProps } from "./code";
import { Icon, type IconSource } from "./icon";
import { Json, type JsonProps, prepareJson } from "./json";
import { MiddleTruncate } from "./middle-truncate";
import { CopyButton } from "./sensitive-editor";

import styles from "./code.module.css";
import frame from "./frame.module.css";

export type CodeBlockProps = Omit<CodeProps, "children" | "block" | "onCopy" | "label"> & {
  children?: React.ReactNode;
  label?: React.ReactNode;
  icon?: IconSource;
  actions?: React.ReactNode;
  copyable?: boolean;
  copyValue?: string;
  copyLabel?: string;
  onCopy?: (value: string) => void;
  writeClipboard?: (value: string) => Promise<void>;
};
export const CodeBlock = ({
  children,
  code,
  label,
  icon,
  actions,
  copyable = true,
  copyValue,
  copyLabel = "Copy code",
  onCopy,
  writeClipboard,
  className,
  ...props
}: CodeBlockProps) => {
  const json =
    React.isValidElement<JsonProps>(children) && children.type === Json ? children : null;
  const source = json
    ? prepareJson(json.props.value, json.props.redact).text
    : (copyValue ?? code ?? (typeof children === "string" ? children : ""));
  const hasCopySource =
    Boolean(json) || copyValue !== undefined || code !== undefined || typeof children === "string";
  const embedded = useInFrame("CodeBlock");
  const labelText = typeof label === "string" ? label : undefined;
  const identityId = React.useId();
  return (
    <section
      data-slot="code-block"
      aria-label={labelText}
      aria-labelledby={label && !labelText ? identityId : undefined}
      data-embedded={embedded || undefined}
      className={cn(!embedded && frame.frame, styles.codeBlock, className)}
    >
      <FrameScope framed>
        {(label || actions || copyable) && (
          <div className={styles.header} data-has-actions={Boolean(actions) || undefined}>
            <div id={identityId} className={styles.identity}>
              {icon && <Icon icon={icon} />}
              {labelText ? (
                <MiddleTruncate keepEnd={16} className={styles.blockLabel}>
                  {labelText}
                </MiddleTruncate>
              ) : (
                label
              )}
            </div>
            {actions && <div className={styles.actions}>{actions}</div>}
            {copyable && (
              <CopyButton
                value={source}
                disabled={!hasCopySource}
                label={copyLabel}
                iconOnly
                onCopy={onCopy}
                writeClipboard={writeClipboard}
              />
            )}
          </div>
        )}
        <div className={cn(frame.frameInset, styles.body)}>
          {json ??
            (typeof children === "string" || children === undefined ? (
              <Code block code={code ?? children} label={labelText} {...props} />
            ) : (
              <div className={styles.customContent}>{children}</div>
            ))}
        </div>
      </FrameScope>
    </section>
  );
};

.code {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  color: var(--cipher-text2, var(--foreground));
}
.inline {
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft, var(--border));
  border-radius: 0;
  padding: var(--cipher-space-2) var(--cipher-space-4);
  background: var(--cipher-tint, var(--muted));
  overflow-wrap: anywhere;
}
.block {
  margin: 0;
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
  tab-size: 2;
  white-space: pre;
  outline-offset: -2px;
}
.wrap {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.line {
  display: inline-block;
  min-height: var(--cipher-type-mono-line-height);
  min-width: 100%;
}
.highlight {
  background: var(--cipher-accent-wash, var(--muted));
  min-width: calc(100% + 2 * var(--cipher-space-surface-inset));
  margin-inline: calc(-1 * var(--cipher-space-surface-inset));
  padding-inline: var(--cipher-space-surface-inset);
}
.number {
  display: inline-block;
  width: 3ch;
  margin-right: var(--cipher-space-content-group);
  text-align: right;
  color: var(--cipher-muted, var(--muted-foreground));
  user-select: none;
}
.codeBlock {
  width: 100%;
}
.codeBlock > .header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-3) var(--cipher-space-4)
    calc(var(--cipher-space-12) - var(--cipher-size-control-border));
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  color: var(--cipher-text2);
}
.codeBlock > .header :global([data-slot="icon"]) {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
  flex: none;
  color: var(--cipher-muted);
}
.body {
  overflow: hidden;
}
.identity {
  grid-column: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-control-gap);
}
.actions {
  grid-column: 2;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: end;
  gap: var(--cipher-space-control-slot-gap);
}
.header > :global([data-slot="copy-button"]) {
  display: contents;
}
.header > :global([data-slot="copy-button"]) > :global(button) {
  grid-column: -2 / -1;
}
.header > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  grid-column: 1 / -1;
}
.customContent {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  padding: var(--cipher-space-surface-inset);
}
.tree {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
}
.entry {
  display: flex;
  align-items: baseline;
  white-space: pre;
}
.treeCaret {
  display: inline-block;
  flex: none;
  width: var(--cipher-space-16);
}
.key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.primitive {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.string {
  color: var(--cipher-text2, var(--foreground));
}
.punctuation {
  color: var(--cipher-muted, var(--muted-foreground));
}
.snippet {
  --cipher-nested-action-height: var(--cipher-size-nested-md);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-control-slot-gap);
  min-width: 0;
  border: var(--cipher-size-control-border) solid var(--cipher-control, var(--border));
  border-radius: 0;
  background: var(--cipher-surface, var(--background));
  padding: var(--cipher-space-control-slot-inset);
  padding-inline-start: var(--cipher-space-control-inline);
  min-height: var(--cipher-size-control-md);
}
.snippetSmall {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-control-sm);
}
.prompt {
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  user-select: none;
}
.input {
  flex: 1;
  width: 0;
  min-width: min(100%, 10ch);
  flex-basis: 10ch;
  border: 0;
  outline: none;
  background: transparent;
  color: inherit;
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.snippet[data-multiline] {
  align-items: flex-start;
}
.snippet[data-multiline] > .prompt {
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
}
/* field-sizing: content ignores rows and is missing in older targets, so the line count also sets a minimum height; content past it scrolls. */
.snippetLines {
  box-sizing: content-box;
  min-height: calc(var(--cipher-snippet-rows) * 1lh);
  max-height: calc(var(--cipher-snippet-lines) * 1lh);
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
  overflow-y: auto;
  resize: none;
  field-sizing: content;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.snippet {
  transition-property: border-color, box-shadow;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.snippet[data-input-focus] {
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.snippet > :global([data-slot="copy-button"]) {
  display: contents;
}
.snippet > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  flex-basis: 100%;
}
.token_comment {
  color: var(--cipher-muted, var(--muted-foreground));
  font-style: italic;
}
.token_string {
  color: var(--cipher-text2, var(--foreground));
}
.token_keyword,
.token_number {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.token_key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.blockLabel {
  flex: 1;
  width: auto;
}
.treeNode {
  min-width: 0;
}
.treeToggle {
  display: inline-flex;
  align-items: center;
  min-width: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-nested-sm);
  text-align: start;
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
}
.treeToggle:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.treeChildren {
  margin-left: calc(var(--cipher-space-6) - var(--cipher-size-control-border));
  padding-left: var(--cipher-space-10);
  border-left: var(--cipher-size-control-border) solid var(--cipher-line);
}
.notice {
  margin: var(--cipher-space-8) 0;
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.wrap .entry {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
@media (max-width: 480px) {
  .header[data-has-actions] .identity {
    grid-column: 1 / -1;
  }
  .header .actions {
    grid-column: 1 / 3;
    justify-content: start;
  }
}

.header[data-has-actions] {
  grid-template-columns: minmax(0, 1fr) auto auto;
}

.frame {
  --cipher-frame-pad: var(--cipher-space-3);
  --cipher-frame-inner-radius: 0;
  min-width: 0;
  padding: var(--cipher-frame-pad);
  background: var(--cipher-tint);
  border: 0;
  border-radius: 0;
}
.frame[data-frame-head] {
  padding-top: 0;
}
.frame[data-frame-foot] {
  padding-bottom: 0;
}
.frameHead,
.frameFoot.frameFoot {
  --cipher-size-control-default: var(--cipher-size-control-band);
}
.frameFoot.frameFoot {
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-6) var(--cipher-space-frame-inline);
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
  border: 0;
  color: var(--cipher-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
}
.frameHead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  justify-content: space-between;
  gap: var(--cipher-space-4) var(--cipher-space-12);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-frame-inline);
  min-width: 0;
}
.frameHead[data-select] {
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
}
.frameHead[data-select] > .frameTitle {
  margin-inline-start: 0;
}
.frameTitle {
  flex: 1 1 var(--cipher-size-cell-min);
  min-width: 0;
  margin-inline-start: var(--cipher-space-frame-title-inline);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cipher-muted);
  text-transform: uppercase;
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
}
.frameTitle[data-hint] {
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
  margin-inline-start: calc(var(--cipher-space-frame-title-inline) - var(--cipher-focus-clearance));
}
.frameTitleHint {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: var(--cipher-faint);
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction {
  flex: none;
  margin-inline-start: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  color: var(--cipher-text2);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-label-font-weight);
}
.frameAction > a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration: underline;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction > a:not([data-slot]):hover {
  color: var(--cipher-text2);
  text-decoration-thickness: var(--cipher-space-2);
}
.frameInset {
  min-width: 0;
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: var(--cipher-frame-inner-radius);
  box-shadow: var(--cipher-shadow-raised);
}
